/* ============================================================
   Biología II · simulacros nuevos (sim6–sim8), formato PAU Madrid 2026.
   Cada simulacro: 5 preguntas de 2 puntos (1 obligatoria competencial + 1 a elegir en cada par 2A/2B, 3A/3B, 4A/4B, 5A/5B), 90 min.
   Entre los tres cubren los 16 temas: bioelementos y agua, glúcidos, lípidos, proteínas y enzimas, ácidos nucleicos,
   célula, núcleo y ciclo celular, respiración, fotosíntesis, genética mendeliana, base molecular de la herencia,
   expresión génica, mutaciones e ingeniería genética, microbiología, inmunología y evolución.
   Todas las cifras están comprobadas con herramientas/verificar_bio2_simulacros.py.
   Masas atómicas: C = 12, H = 1, O = 16. R = 0,082 atm·L/(mol·K). ATP por NADH = 2,5 y por FADH₂ = 1,5.
   ============================================================ */
(function (global) {
  "use strict";
  var B = global.BACHI;
  var CR = "<br><b>Criterios de puntuación: </b>";
  var INSTR = "<i><b>Instrucciones (formato PAU Madrid 2026, 90 min).</b> Cinco preguntas de 2 puntos cada una: la pregunta 1, obligatoria y de carácter competencial, y una a elegir en cada par 2A/2B, 3A/3B, 4A/4B y 5A/5B. La puntuación de cada apartado figura entre paréntesis. Nota: la estructura (5 preguntas, la 1 competencial sin opción, opción A/B en las demás, hasta 2 puntos por pregunta en múltiplos de 0,1 y 90 min) procede de la reunión informativa oficial de Biología (<a href=\"https://www.uam.es/uam/media/doc/1606968075323/presentacion-biologia-04112025.pdf\" target=\"_blank\" rel=\"noopener\">presentación PAU 2026 de Biología, UAM</a>) y de su <a href=\"https://www.uam.es/uam/media/doc/1606850470206/pau-2026-acta-reunion-biologia.pdf\" target=\"_blank\" rel=\"noopener\">acta</a>; el reparto de puntos entre apartados y qué bloque de contenidos cae en cada pregunta está deducido (reparto deducido), porque esos documentos no lo fijan.</i><br>";
  function etiq(n, par) { return "<i>Pregunta " + n + ": elige una de " + par + " (2 puntos; la puntuación de cada apartado figura entre paréntesis).</i><br>"; }
  var E2A = etiq("2A", "2A o 2B"), E2B = etiq("2B", "2A o 2B"), E3A = etiq("3A", "3A o 3B"), E3B = etiq("3B", "3A o 3B"),
      E4A = etiq("4A", "4A o 4B"), E4B = etiq("4B", "4A o 4B"), E5A = etiq("5A", "5A o 5B"), E5B = etiq("5B", "5A o 5B");
  var TD = function (a) { return "<tr><td>" + a.join("</td><td>") + "</td></tr>"; };
  var TH = function (a) { return "<tr><th>" + a.join("</th><th>") + "</th></tr>"; };
  function tabla(cab, filas) { return "<div style='overflow-x:auto;max-width:100%'><table class='lamina-table'>" + TH(cab) + filas.map(TD).join("") + "</table></div>"; }

  B.registrarSimulacros("bio2", [

    // ------------------------------------------------------------------ sim6
    { id: "sim6", titulo: "Simulacro 6 · Biología II (formato PAU Madrid 2026)", tipo: "ciencias",
      bloques: [
        { titulo: "Pregunta 1 (obligatoria) · Enzimas y cofactores", puntos: 2,
          enunciado: INSTR + "Un laboratorio estudia una enzima que necesita Mg²⁺ como cofactor. Mide su velocidad inicial (µmol/min) con distintas concentraciones de sustrato, sin inhibidor y con un inhibidor I a concentración fija:<br>" +
            tabla(["[S] (mM)", "0,5", "1", "2", "4", "8", "16"], [["v sin I", "20,0", "33,3", "50,0", "66,7", "80,0", "88,9"], ["v con I", "7,7", "14,3", "25,0", "40,0", "57,1", "72,7"]]) +
            "a) Estima la V<sub>máx</sub> y la K<sub>m</sub> de la enzima sin inhibidor y explica qué significa K<sub>m</sub>. (0,6)<br>b) Con el inhibidor, la V<sub>máx</sub> no cambia y la K<sub>m</sub> aparente es 6 mM. ¿De qué tipo de inhibición se trata? Razónalo e indica cómo podría superarse. (0,7)<br>c) Calcula la velocidad con I a [S] = 40 mM. (0,4)<br>d) El Mg²⁺ es un bioelemento secundario. Explica qué papel tiene como cofactor y qué le ocurre a la actividad si la enzima se calienta a 80 °C. (0,3)",
          solucion: "a) La velocidad se acerca a un máximo: <b>V<sub>máx</sub> = 100 µmol/min</b> (con [S] = 16 mM se alcanza el 88,9 %). K<sub>m</sub> es la [S] a la que v = V<sub>máx</sub>/2 = 50 µmol/min; en la tabla ocurre a [S] = 2 mM: <b>K<sub>m</sub> = 2 mM</b>. Mide la afinidad: cuanto menor es K<sub>m</sub>, mayor afinidad por el sustrato.<br>b) Es una <b>inhibición competitiva</b>: la V<sub>máx</sub> no cambia (con [S] muy alta se alcanza igual) y la K<sub>m</sub> aparente aumenta de 2 a 6 mM (hace falta más sustrato para llegar a V<sub>máx</sub>/2). El inhibidor se parece al sustrato y compite por el sitio activo; se supera <b>aumentando la [S]</b>, porque el sustrato desplaza al inhibidor.<br>c) v = V<sub>máx</sub>·[S]/(K<sub>m</sub>' + [S]) = 100·40/(6 + 40) = <b>87,0 µmol/min</b> (sin inhibidor sería 95,2).<br>d) El cofactor inorgánico se une a la enzima (o al sustrato, p. ej. ATP–Mg²⁺) y es necesario para que la catálisis ocurra. A 80 °C la proteína se <b>desnaturaliza</b> (pierde su estructura terciaria y el sitio activo) y la actividad cae casi a cero." +
            CR + "a) 0,3 por V<sub>máx</sub>, 0,2 por K<sub>m</sub> y 0,1 por su significado; b) 0,3 por «competitiva», 0,3 por el razonamiento con V<sub>máx</sub> y K<sub>m</sub> y 0,1 por cómo superarla; c) 0,2 por la fórmula y 0,2 por el valor; d) 0,2 por el cofactor y 0,1 por la desnaturalización." },
        { titulo: "Pregunta 2A · Lípidos", puntos: 2,
          enunciado: E2A + "La tripalmitina es un triglicérido formado por glicerol (C₃H₈O₃, M = 92 g/mol) y tres moléculas de ácido palmítico (C₁₆H₃₂O₂, M = 256 g/mol).<br>a) Escribe la reacción de formación, indica el tipo de enlace y calcula la masa molar de la tripalmitina. (0,6)<br>b) Calcula la masa de tripalmitina que se obtiene a partir de 9,2 g de glicerol con exceso de ácido y rendimiento del 100 %. (0,6)<br>c) Escribe los productos de su saponificación con NaOH y explica por qué el jabón actúa como emulgente. (0,4)<br>d) Diferencia un ácido graso saturado de uno insaturado y relaciónalo con que el aceite de oliva sea líquido y la mantequilla sólida. (0,4)",
          solucion: "a) <b>Glicerol + 3 ácido palmítico → tripalmitina + 3 H₂O</b> (esterificación; tres <b>enlaces éster</b>, uno por cada –OH del glicerol). M = 92 + 3·256 − 3·18 = <b>806 g/mol</b> (C₅₁H₉₈O₆).<br>b) n(glicerol) = 9,2/92 = 0,10 mol; 1 mol de glicerol da 1 mol de triglicérido → 0,10 mol · 806 = <b>80,6 g</b>.<br>c) La saponificación (hidrólisis alcalina) da <b>glicerol y tres sales sódicas del ácido graso (palmitato sódico, el jabón)</b>. El jabón es <b>anfipático</b>: la cola hidrófoba se une a la grasa y la cabeza iónica hidrófila al agua, de modo que forma micelas que dispersan la grasa (emulsión).<br>d) Un ácido graso <b>saturado</b> no tiene dobles enlaces C=C y su cadena es recta, así que las moléculas se empaquetan bien y hay muchas fuerzas de dispersión entre ellas (sólido a temperatura ambiente, mantequilla). Uno <b>insaturado</b> tiene dobles enlaces (normalmente cis) que doblan la cadena, se empaquetan peor y el punto de fusión es menor (aceite de oliva, líquido)." +
            CR + "a) 0,3 por la reacción con 3 H₂O, 0,1 por el enlace éster y 0,2 por la masa molar; b) 0,3 por los moles y 0,3 por la masa; c) 0,2 por los productos y 0,2 por el carácter anfipático; d) 0,2 por la diferencia estructural y 0,2 por la relación con el punto de fusión." },
        { titulo: "Pregunta 2B · Bioelementos, agua y sales minerales", puntos: 2,
          enunciado: E2B + "Los eritrocitos humanos están en equilibrio en suero fisiológico, NaCl al 0,9 % (p/v). M(NaCl) = 58,5 g/mol; M(glucosa) = 180 g/mol.<br>a) Calcula la molaridad del suero y su osmolaridad (el NaCl se disocia por completo). (0,6)<br>b) Explica, usando la ósmosis, qué les ocurre a los eritrocitos en agua destilada y en NaCl al 3 %. (0,5)<br>c) ¿Será aproximadamente isotónica una disolución de glucosa de 54 g/L? Calcula su osmolaridad. (0,5)<br>d) Cita dos propiedades del agua debidas a los puentes de hidrógeno y su importancia biológica. (0,4)",
          solucion: "a) 0,9 % = 9 g/L → 9/58,5 = <b>0,154 M</b>. NaCl → Na⁺ + Cl⁻ (2 partículas por fórmula): osmolaridad = 2·0,154 = <b>0,308 osmol/L</b>.<br>b) En <b>agua destilada</b> el medio es hipotónico: el agua entra en el eritrocito (hacia la zona de mayor concentración de solutos), la célula se hincha y estalla (<b>hemólisis</b>). En NaCl al 3 % el medio es hipertónico: el agua sale, la célula se arruga (<b>crenación</b>).<br>c) 54/180 = 0,300 M y la glucosa no se disocia, así que la osmolaridad es <b>0,300 osmol/L</b>, muy próxima a 0,308 (diferencia &lt; 3 %): es <b>aproximadamente isotónica</b>, y los eritrocitos conservarían su forma.<br>d) Por ejemplo: <b>elevado calor específico y de vaporización</b> (amortigua los cambios de temperatura y permite refrigerar por sudoración) y <b>alto poder disolvente</b> de sustancias polares e iónicas (medio de las reacciones metabólicas y del transporte). También: cohesión y tensión superficial, o densidad máxima a 4 °C." +
            CR + "a) 0,3 por la molaridad y 0,3 por la osmolaridad con el factor 2; b) 0,25 por cada medio con el sentido del movimiento del agua; c) 0,3 por el cálculo y 0,2 por la conclusión; d) 0,2 por cada propiedad con su importancia." },
        { titulo: "Pregunta 3A · Respiración celular", puntos: 2,
          enunciado: E3A + "Se estudia la oxidación completa de una molécula de glucosa en una célula eucariota con oxígeno.<br>a) Completa, para una molécula de glucosa, cuántos ATP (o GTP) netos, NADH y FADH₂ se forman en la glucólisis, en la descarboxilación oxidativa del piruvato y en el ciclo de Krebs. (0,8)<br>b) Calcula el ATP total, suponiendo 2,5 ATP por NADH y 1,5 por FADH₂ (incluidos los NADH de la glucólisis). (0,6)<br>c) Compara con la fermentación láctica, que rinde 2 ATP por glucosa. (0,3)<br>d) Indica en qué parte de la célula ocurre cada etapa y cuál es el aceptor final de electrones. (0,3)",
          solucion: "a) <b>Glucólisis</b>: 2 ATP netos, 2 NADH, 0 FADH₂. <b>Descarboxilación del piruvato</b> (2 piruvatos): 0 ATP, 2 NADH. <b>Ciclo de Krebs</b> (2 vueltas): 2 GTP (≈ ATP), 6 NADH, 2 FADH₂. Total por glucosa: <b>4 ATP/GTP, 10 NADH y 2 FADH₂</b>.<br>b) 4 + 10·2,5 + 2·1,5 = 4 + 25 + 3 = <b>32 ATP por glucosa</b>. (Con las cifras clásicas 3 y 2 ATP, se obtienen 38; ambas respuestas son válidas si se indica el criterio.)<br>c) La fermentación láctica da 2 ATP: la respiración aerobia rinde 32/2 = <b>16 veces más</b> energía útil, porque en la fermentación el piruvato no se oxida del todo y no hay cadena respiratoria.<br>d) Glucólisis: <b>citosol</b>. Descarboxilación del piruvato y ciclo de Krebs: <b>matriz mitocondrial</b>. Cadena de transporte de electrones y fosforilación oxidativa: <b>crestas de la membrana mitocondrial interna</b>. El aceptor final es el <b>O₂</b>, que se reduce a H₂O." +
            CR + "a) 0,2 por cada etapa y 0,2 por los totales; b) 0,3 por la fórmula y 0,3 por el resultado; c) 0,2 por la comparación numérica y 0,1 por la razón; d) 0,2 por las localizaciones y 0,1 por el O₂." },
        { titulo: "Pregunta 3B · Fotosíntesis", puntos: 2,
          enunciado: E3B + "Se ilumina una planta con distinta intensidad y se mide el oxígeno neto liberado (µmol O₂/h; los valores negativos son consumo):<br>" +
            tabla(["Intensidad (unidades)", "0", "10", "20", "40", "80", "120"], [["O₂ neto", "−4", "0", "6", "14", "20", "20"]]) +
            "a) ¿Qué representa el valor en la oscuridad? Define el punto de compensación e indica su valor. (0,5)<br>b) Calcula la fotosíntesis bruta con intensidades de 40 y de 120 unidades. (0,5)<br>c) A partir de 80 unidades el O₂ ya no aumenta: ¿qué ocurre y qué factores pueden limitarlo? (0,5)<br>d) Para formar una molécula de glucosa en el ciclo de Calvin a partir de 6 CO₂ se necesitan 18 ATP y 12 NADPH. ¿En qué fase de la fotosíntesis se producen y dónde? (0,5)",
          solucion: "a) En la oscuridad no hay fotosíntesis: el −4 mide la <b>respiración</b> (consumo de 4 µmol O₂/h). El <b>punto de compensación</b> es la intensidad a la que el O₂ producido por la fotosíntesis iguala al consumido por la respiración (O₂ neto = 0): <b>10 unidades</b>.<br>b) Fotosíntesis bruta = O₂ neto + respiración. A 40 unidades: 14 + 4 = <b>18 µmol O₂/h</b>. A 120 unidades: 20 + 4 = <b>24 µmol O₂/h</b>.<br>c) Se alcanza la <b>saturación lumínica</b>: la luz deja de ser el factor limitante. Pasan a limitar la <b>concentración de CO₂</b>, la temperatura (actividad de la rubisco y de las enzimas del ciclo de Calvin), el agua (cierre de estomas) o la cantidad de pigmentos y enzimas.<br>d) Se producen en la <b>fase luminosa</b> (dependiente de la luz), en las <b>membranas de los tilacoides</b>: la cadena de transporte de electrones produce NADPH y el gradiente de protones permite a la ATP sintasa formar ATP. Se consumen en el ciclo de Calvin, en el estroma." +
            CR + "a) 0,2 por la respiración, 0,2 por la definición y 0,1 por el valor; b) 0,25 por cada valor con el razonamiento; c) 0,3 por la saturación y 0,2 por dos factores; d) 0,25 por la fase y 0,25 por el lugar." },
        { titulo: "Pregunta 4A · Genética mendeliana", puntos: 2,
          enunciado: E4A + "La fenilcetonuria (PKU) es un trastorno autosómico recesivo. Una pareja sin la enfermedad tiene un hijo con PKU.<br>a) Indica los genotipos de los padres y del hijo (alelos A y a). (0,5)<br>b) ¿Qué probabilidad hay de que el siguiente hijo tenga PKU? ¿Y de que sea sano y portador? (0,5)<br>c) Si tienen dos hijos más, calcula la probabilidad de que ninguno tenga PKU y la de que exactamente uno la tenga. (0,6)<br>d) Una hija de la pareja es sana: ¿qué probabilidad hay de que sea portadora? (0,4)",
          solucion: "a) El hijo enfermo es <b>aa</b>; ha recibido un alelo a de cada progenitor, que son sanos, luego ambos son <b>Aa</b> (portadores).<br>b) Aa × Aa → 1/4 AA, 1/2 Aa, 1/4 aa. Probabilidad de PKU = <b>1/4 (25 %)</b>; sano y portador (Aa) = <b>1/2 (50 %)</b>.<br>c) Cada hijo es independiente: sano con probabilidad 3/4. Ninguno afectado: (3/4)² = <b>9/16</b>. Exactamente uno: 2·(1/4)·(3/4) = <b>3/8</b> (6/16).<br>d) Entre los hijos sanos solo cuentan AA (1/4) y Aa (1/2): P(portadora | sana) = (1/2)/(3/4) = <b>2/3</b>." +
            CR + "a) 0,2 por cada genotipo de los padres y 0,1 por el del hijo con razonamiento; b) 0,25 por cada probabilidad; c) 0,3 por cada probabilidad; d) 0,2 por plantear la probabilidad condicionada y 0,2 por el valor." },
        { titulo: "Pregunta 4B · Expresión génica: transcripción y traducción", puntos: 2,
          enunciado: E4B + "Un fragmento de un gen tiene la cadena molde 3′-TAC CCT CTA AAC ATT-5′. Datos del código genético: AUG = Met; GGA, GGG = Gly; GAU = Asp; GAA, GAG = Glu; UUG = Leu; AUU = Ile; UGU = Cys; UAA, UAG = parada.<br>a) Escribe el ARNm resultante (5′→3′). (0,5)<br>b) Escribe el péptido que se forma. (0,6)<br>c) Indica el efecto de cada cambio en el ARNm: (i) GGA → GGG; (ii) GAU → GAA; (iii) UUG → UAG. (0,5)<br>d) Si se elimina el cuarto nucleótido del ARNm (la primera G de GGA), ¿qué ocurre con el péptido? (0,4)",
          solucion: "a) La ARN polimerasa lee la cadena molde en sentido 3′→5′ y sintetiza el ARNm complementario (con U en lugar de T): 3′-TAC CCT CTA AAC ATT-5′ → <b>5′-AUG GGA GAU UUG UAA-3′</b>.<br>b) AUG-GGA-GAU-UUG-UAA → <b>Met-Gly-Asp-Leu</b> (UAA es codón de parada, no codifica aminoácido).<br>c) (i) GGA → GGG: sigue siendo Gly, <b>mutación silenciosa</b> (el código está degenerado). (ii) GAU → GAA: Asp → Glu, <b>mutación de cambio de sentido</b> (un aminoácido distinto). (iii) UUG → UAG: aparece un codón de parada en la posición 4, <b>mutación sin sentido</b> → péptido truncado de 3 aminoácidos (Met-Gly-Asp).<br>d) Es una <b>mutación por deleción que desplaza el marco de lectura</b>: AUG GAG AUU UGU AA… → <b>Met-Glu-Ile-Cys</b> y a partir de ahí todo el péptido cambia respecto al original (no aparece el codón de parada en su sitio): un cambio mucho más grave que una sustitución." +
            CR + "a) 0,3 por la complementariedad con U y 0,2 por la polaridad; b) 0,4 por los aminoácidos y 0,2 por la parada; c) 0,15 + 0,15 + 0,2; d) 0,2 por el péptido alterado y 0,2 por explicar el desplazamiento del marco." },
        { titulo: "Pregunta 5A · Microbiología", puntos: 2,
          enunciado: E5A + "Un cultivo de <i>Escherichia coli</i> parte de 1,0·10³ bacterias/mL. En fase exponencial su tiempo de generación es de 20 min.<br>a) Nombra las fases de una curva de crecimiento bacteriano y di qué ocurre en la exponencial. (0,5)<br>b) Calcula cuántas bacterias/mL habrá tras 3 h de crecimiento exponencial. (0,6)<br>c) ¿Cuánto tiempo tarda en alcanzar 1,0·10⁹ bacterias/mL? (0,6)<br>d) La penicilina mata bacterias pero no virus ni células humanas: explica por qué. (0,3)",
          solucion: "a) <b>Latencia</b> (adaptación, casi sin división), <b>exponencial</b> (división constante: la población se duplica en cada tiempo de generación), <b>estacionaria</b> (nacen tantas bacterias como mueren por falta de nutrientes y acumulación de residuos) y <b>declive o muerte</b>.<br>b) 3 h = 180 min → 180/20 = 9 generaciones. N = 1,0·10³ · 2⁹ = 1000 · 512 = <b>5,12·10⁵ bacterias/mL</b>.<br>c) 1,0·10⁹ = 1,0·10³ · 2<sup>n</sup> → 2<sup>n</sup> = 10⁶ → n = log₂(10⁶) = 19,93 generaciones → t = 19,93 · 20 = 398,6 min ≈ <b>6,6 h (6 h 39 min)</b>.<br>d) La penicilina impide la síntesis de la <b>pared de peptidoglucano</b> de las bacterias: estas se lisan por presión osmótica. Los virus no tienen metabolismo ni pared, y las células humanas no tienen peptidoglucano." +
            CR + "a) 0,3 por las cuatro fases y 0,2 por la exponencial; b) 0,3 por las generaciones y 0,3 por N; c) 0,3 por plantear 2<sup>n</sup> = 10⁶, 0,2 por n y 0,1 por t; d) 0,2 por la pared y 0,1 por la razón de la selectividad." },
        { titulo: "Pregunta 5B · Evolución: genética de poblaciones", puntos: 2,
          enunciado: E5B + "En una población de 5000 individuos, el 4 % muestra un rasgo recesivo (aa). Se supone que está en equilibrio de Hardy-Weinberg.<br>a) Enumera las condiciones del equilibrio de Hardy-Weinberg. (0,5)<br>b) Calcula las frecuencias de los alelos A y a y de los tres genotipos, y el número esperado de individuos de cada genotipo. (0,8)<br>c) Si una selección eliminase a todos los aa antes de reproducirse, ¿cuál sería la frecuencia de a en la generación siguiente? (0,4)<br>d) Cita dos factores que alteren el equilibrio y explica cuál produce adaptación. (0,3)",
          solucion: "a) Población <b>grande</b>, apareamiento <b>al azar</b>, <b>sin mutación</b>, <b>sin migración</b> (flujo génico) y <b>sin selección natural</b>.<br>b) q² = 0,04 → <b>q = 0,2</b> y <b>p = 0,8</b>. Genotipos: AA = p² = 0,64; Aa = 2pq = 0,32; aa = q² = 0,04. En 5000 individuos: <b>AA = 3200, Aa = 1600, aa = 200</b>.<br>c) Quedan solo AA (0,64) y Aa (0,32), que suman 0,96. Los alelos a son los de Aa: q′ = (0,32/2)/0,96 = 0,16/0,96 = <b>0,167</b> (de 0,20 a 0,167).<br>d) Por ejemplo la <b>mutación</b>, la <b>deriva genética</b> (poblaciones pequeñas), la <b>migración</b> y la <b>selección natural</b>. Solo la selección natural conduce a la adaptación: favorece los alelos que aumentan la eficacia biológica (supervivencia y reproducción) en un ambiente concreto." +
            CR + "a) 0,1 por cada condición; b) 0,3 por p y q, 0,3 por las frecuencias genotípicas y 0,2 por los números; c) 0,2 por plantear con la población que queda y 0,2 por el valor; d) 0,1 por cada factor y 0,1 por indicar la selección natural." }
      ] },

    // ------------------------------------------------------------------ sim7
    { id: "sim7", titulo: "Simulacro 7 · Biología II (formato PAU Madrid 2026)", tipo: "ciencias",
      bloques: [
        { titulo: "Pregunta 1 (obligatoria) · Ciclo celular y división", puntos: 2,
          enunciado: INSTR + "Un laboratorio estudia una línea celular cuyo ciclo dura 20 h. Mide por citometría de flujo el contenido de ADN de 10 000 células de un cultivo asíncrono (C = cantidad de ADN de un juego haploide):<br>" +
            tabla(["Contenido de ADN", "2C", "entre 2C y 4C", "4C"], [["Nº de células", "5500", "2400", "2100"]]) +
            "a) Asigna cada grupo a una fase del ciclo y calcula la duración de G₁, S y G₂ + M, suponiendo que la fracción de células en cada fase es proporcional a su duración. (0,6)<br>b) Se añade colchicina, que impide formar el huso mitótico. ¿Cómo cambiará el histograma con el tiempo? (0,5)<br>c) Un organismo tiene 2n = 8. Indica el número de cromosomas y de cromátidas de una célula en metafase de la mitosis y en metafase II de la meiosis. (0,5)<br>d) Explica dos mecanismos por los que la meiosis genera variabilidad. (0,4)",
          solucion: "a) 2C = <b>G₁</b> (aún no ha replicado); entre 2C y 4C = <b>S</b> (replicación en curso); 4C = <b>G₂ + mitosis</b> (ADN ya duplicado). Duración = fracción · 20 h: G₁ = 0,55 · 20 = <b>11 h</b>; S = 0,24 · 20 = <b>4,8 h</b>; G₂ + M = 0,21 · 20 = <b>4,2 h</b>.<br>b) La colchicina bloquea las células en <b>metafase</b> (4C): el pico de 4C aumentará con el tiempo y el de 2C disminuirá, porque las células que salían de la mitosis a G₁ ya no lo hacen.<br>c) <b>Metafase mitótica</b>: 8 cromosomas, cada uno con 2 cromátidas → <b>16 cromátidas</b>. <b>Metafase II</b>: la célula es haploide (n = 4) → <b>4 cromosomas y 8 cromátidas</b>.<br>d) <b>Entrecruzamiento (recombinación)</b> entre cromátidas de cromosomas homólogos en la profase I, y <b>segregación independiente</b> de los cromosomas homólogos en la anafase I (con n = 4 hay 2⁴ = 16 combinaciones posibles sin contar el entrecruzamiento)." +
            CR + "a) 0,3 por asignar las fases y 0,1 por cada duración; b) 0,3 por la acumulación en metafase y 0,2 por el efecto sobre cada pico; c) 0,25 por cada fase (cromosomas y cromátidas); d) 0,2 por cada mecanismo." },
        { titulo: "Pregunta 2A · Proteínas", puntos: 2,
          enunciado: E2A + "El tripéptido Gly–Ala–Ser está formado por glicina (M = 75 g/mol), alanina (M = 89 g/mol) y serina (M = 105 g/mol).<br>a) Dibuja la fórmula general de un aminoácido y el enlace peptídico que une dos de ellos. (0,5)<br>b) Calcula la masa molecular del tripéptido. (0,6)<br>c) ¿Cuántos tripéptidos distintos pueden formarse con estos tres aminoácidos, usando cada uno una vez? ¿Cuántos tetrapéptidos distintos son posibles con los 20 aminoácidos proteicos? (0,5)<br>d) Define los niveles de estructura de una proteína y di qué cambia en la desnaturalización. (0,4)",
          solucion: "a) Aminoácido: un carbono α unido a un grupo amino (–NH₂), un carboxilo (–COOH), un H y una cadena lateral R. El <b>enlace peptídico</b> es un enlace amida –CO–NH– entre el carboxilo de un aminoácido y el amino del siguiente, con pérdida de una molécula de agua; es rígido y plano.<br>b) M = 75 + 89 + 105 − 2·18 = 269 − 36 = <b>233 g/mol</b> (se pierden 2 H₂O: hay 2 enlaces peptídicos).<br>c) Ordenaciones de 3 elementos distintos: 3! = <b>6</b> tripéptidos. Tetrapéptidos con 20 aminoácidos: 20⁴ = <b>160 000</b>.<br>d) <b>Primaria</b>: secuencia de aminoácidos; <b>secundaria</b>: plegamiento local (hélice α, lámina β) por puentes de hidrógeno; <b>terciaria</b>: plegamiento tridimensional de toda la cadena (puentes disulfuro, interacciones hidrófobas, iónicas…); <b>cuaternaria</b>: unión de varias cadenas. En la <b>desnaturalización</b> se pierden las estructuras secundaria, terciaria y cuaternaria, pero no la primaria (los enlaces peptídicos siguen intactos), y la proteína pierde su función." +
            CR + "a) 0,3 por la fórmula y 0,2 por el enlace; b) 0,3 por restar 2 H₂O y 0,3 por el valor; c) 0,25 por cada cálculo; d) 0,2 por los niveles y 0,2 por la desnaturalización." },
        { titulo: "Pregunta 2B · Ácidos nucleicos", puntos: 2,
          enunciado: E2B + "Un fragmento de ADN bicatenario de 1000 pares de bases contiene un 28 % de adenina.<br>a) Calcula el porcentaje de T, G y C y el número de nucleótidos de cada base del fragmento. (0,7)<br>b) Calcula el número de enlaces de hidrógeno entre las dos cadenas. (0,5)<br>c) Otro fragmento de 1000 pares de bases tiene un 28 % de guanina. ¿Cuál tiene mayor temperatura de fusión? Razónalo. (0,4)<br>d) Indica tres diferencias entre el ADN y el ARN. (0,4)",
          solucion: "a) Por la regla de Chargaff, A = T → <b>T = 28 %</b>; A + T = 56 %, así que G + C = 44 % y <b>G = C = 22 %</b>. El fragmento tiene 2000 nucleótidos: A = T = 0,28·2000 = <b>560</b>; G = C = 0,22·2000 = <b>440</b>.<br>b) A–T forman 2 enlaces de hidrógeno y G–C forman 3: 560·2 + 440·3 = 1120 + 1320 = <b>2440 enlaces</b>.<br>c) Con 28 % de G: G = C = 560 y A = T = 440 → 440·2 + 560·3 = 2560 enlaces. El segundo fragmento (56 % de G + C) tiene <b>mayor temperatura de fusión</b>: más pares G–C, con 3 enlaces de hidrógeno, hay que aportar más energía para separar las cadenas.<br>d) El ADN tiene <b>desoxirribosa</b>, el ARN <b>ribosa</b>; el ADN tiene <b>timina</b> y el ARN <b>uracilo</b>; el ADN es normalmente <b>bicatenario</b> (doble hélice) y el ARN <b>monocatenario</b>. (También: función y tamaño.)" +
            CR + "a) 0,2 por T, 0,2 por G y C y 0,3 por los números; b) 0,3 por plantear 2 y 3 enlaces y 0,2 por el total; c) 0,2 por la elección y 0,2 por el razonamiento; d) 0,15 por cada diferencia (hasta 0,4)." },
        { titulo: "Pregunta 3A · La célula eucariota", puntos: 2,
          enunciado: E3A + "En una micrografía electrónica ampliada 15 000 veces, una mitocondria mide 45 mm de longitud.<br>a) Calcula su tamaño real en micrómetros. (0,5)<br>b) La mitocondria y el cloroplasto tienen doble membrana y ADN propio. Explica la teoría endosimbiótica y aporta dos pruebas a su favor. (0,6)<br>c) Describe el recorrido de una proteína de secreción (por ejemplo, la insulina) por los orgánulos de la célula. (0,5)<br>d) Indica tres diferencias entre una célula procariota y una eucariota. (0,4)",
          solucion: "a) Tamaño real = tamaño en la imagen / aumento = 45 mm / 15 000 = 3,0·10⁻³ mm = <b>3,0 µm</b>.<br>b) Según la <b>teoría endosimbiótica</b> (Margulis), mitocondrias y cloroplastos proceden de procariotas (una bacteria aerobia y una cianobacteria) englobadas por una célula ancestral, con la que establecieron una simbiosis. Pruebas: tienen <b>ADN circular propio</b> y <b>ribosomas 70S</b> (como las bacterias) y se dividen por <b>fisión binaria</b>, de forma independiente de la célula; además, su doble membrana se explica porque la interna sería la de la bacteria original y la externa, la de la vesícula de fagocitosis.<br>c) Se sintetiza en los ribosomas del <b>retículo endoplasmático rugoso</b> y entra en su luz; pasa en vesículas al <b>aparato de Golgi</b> (maduración y empaquetado) y sale en <b>vesículas de secreción</b> que se fusionan con la membrana plasmática (exocitosis).<br>d) La procariota <b>no tiene núcleo</b> (ADN libre en el nucleoide), <b>no tiene orgánulos membranosos</b>, tiene ribosomas 70S (los eucariotas 80S) y es mucho más pequeña (1–5 µm frente a 10–100 µm); su ADN es circular y sin histonas." +
            CR + "a) 0,3 por el planteamiento y 0,2 por el resultado con unidades; b) 0,3 por la teoría y 0,15 por cada prueba; c) 0,2 por RER, 0,2 por Golgi y 0,1 por la secreción; d) 0,15 por cada diferencia (hasta 0,4)." },
        { titulo: "Pregunta 3B · Fermentación alcohólica", puntos: 2,
          enunciado: E3B + "Unas levaduras fermentan en ausencia de oxígeno 90 g de glucosa (M = 180 g/mol). M(etanol) = 46 g/mol.<br>a) Escribe la reacción global e indica dónde ocurre. (0,5)<br>b) Calcula la masa de etanol y el volumen de CO₂ a 25 °C y 1 atm. (0,7)<br>c) Calcula los moles de ATP netos formados y compáralos con los de la respiración aerobia (32 ATP por glucosa). (0,4)<br>d) ¿Qué función tiene la reducción del piruvato en la fermentación? (0,4)",
          solucion: "a) <b>C₆H₁₂O₆ → 2 CH₃CH₂OH + 2 CO₂</b> (con 2 ATP netos). Ocurre en el <b>citosol</b> (glucólisis seguida de la reducción del piruvato).<br>b) n(glucosa) = 90/180 = 0,50 mol → n(etanol) = 2·0,50 = 1,0 mol → m = 1,0·46 = <b>46 g</b>. n(CO₂) = 1,0 mol → V = nRT/P = 1,0·0,082·298/1 = <b>24,4 L</b>.<br>c) 2 ATP por glucosa → 0,50·2 = <b>1,0 mol de ATP</b>. En respiración aerobia: 0,50·32 = 16 mol, es decir, <b>16 veces más</b>.<br>d) Regenera el <b>NAD⁺</b> (el NADH formado en la glucólisis cede sus electrones al acetaldehído, que se reduce a etanol). Sin NAD⁺ la glucólisis se pararía y la célula dejaría de obtener ATP." +
            CR + "a) 0,3 por la reacción y 0,2 por el citosol; b) 0,3 por el etanol y 0,4 por el volumen; c) 0,2 por el ATP y 0,2 por la comparación; d) 0,2 por la regeneración de NAD⁺ y 0,2 por la consecuencia." },
        { titulo: "Pregunta 4A · Base molecular de la herencia: replicación", puntos: 2,
          enunciado: E4A + "En el experimento de Meselson y Stahl, <i>E. coli</i> se cultivó durante muchas generaciones con ¹⁵N (ADN pesado) y después se pasó a un medio con ¹⁴N (ADN ligero).<br>a) Indica la proporción de ADN híbrido (¹⁵N/¹⁴N) y de ADN ligero (¹⁴N/¹⁴N) tras 1, 2 y 3 generaciones. (0,6)<br>b) ¿Qué modelos de replicación descartan los resultados tras la primera y la segunda generación? (0,5)<br>c) Nombra las funciones de la helicasa, la ADN polimerasa y la ligasa. (0,5)<br>d) El cromosoma de <i>E. coli</i> tiene 4,6·10⁶ pb y se replica desde un solo origen en dos direcciones, con 1000 nucleótidos por segundo en cada horquilla. Calcula el tiempo de replicación. (0,4)",
          solucion: "a) La replicación es <b>semiconservativa</b>: cada molécula hija conserva una hebra antigua (¹⁵N). Generación 1: <b>100 % híbrido</b>. Generación 2: <b>50 % híbrido y 50 % ligero</b>. Generación 3: <b>25 % híbrido y 75 % ligero</b> (2 de 8 moléculas conservan una hebra ¹⁵N).<br>b) Tras la <b>primera</b> generación solo hay una banda híbrida: se descarta el modelo <b>conservativo</b> (habría una banda pesada y otra ligera). Tras la <b>segunda</b>, hay una banda híbrida y otra ligera: se descarta el modelo <b>dispersivo</b> (habría una sola banda de densidad intermedia).<br>c) La <b>helicasa</b> separa las dos hebras (rompe los puentes de hidrógeno) y abre la horquilla; la <b>ADN polimerasa</b> añade desoxirribonucleótidos en sentido 5′→3′ complementarios al molde; la <b>ligasa</b> une los fragmentos de Okazaki de la hebra retardada.<br>d) Cada horquilla copia la mitad del cromosoma: 4,6·10⁶/2 = 2,3·10⁶ nucleótidos a 1000 nt/s → t = 2300 s ≈ <b>38 min</b> (38,3 min)." +
            CR + "a) 0,2 por cada generación; b) 0,25 por cada modelo con su razón; c) 0,15 por la helicasa, 0,2 por la polimerasa y 0,15 por la ligasa; d) 0,2 por dividir entre las dos horquillas y 0,2 por el tiempo." },
        { titulo: "Pregunta 4B · Herencia ligada al sexo y grupos sanguíneos", puntos: 2,
          enunciado: E4B + "El daltonismo es un carácter recesivo ligado al cromosoma X (X<sup>d</sup>). Una mujer de visión normal, portadora, y un hombre de visión normal tienen hijos.<br>a) Indica los genotipos y fenotipos de los hijos y la probabilidad de que un hijo varón sea daltónico y de que lo sea un hijo cualquiera. (0,6)<br>b) Si el padre fuera daltónico y la madre portadora, ¿qué probabilidad hay de que una hija sea daltónica? (0,4)<br>c) Una mujer de grupo A (heterocigótica) y un hombre de grupo B (heterocigótico) tienen hijos. Indica los fenotipos posibles y la probabilidad de que dos hijos sean ambos del grupo O. (0,6)<br>d) Explica por qué un individuo I<sup>A</sup>I<sup>B</sup> es del grupo AB. (0,4)",
          solucion: "a) X<sup>D</sup>X<sup>d</sup> × X<sup>D</sup>Y. Hijas: 1/2 X<sup>D</sup>X<sup>D</sup> (normal) y 1/2 X<sup>D</sup>X<sup>d</sup> (normal, portadora); hijos: 1/2 X<sup>D</sup>Y (normal) y 1/2 X<sup>d</sup>Y (daltónico). Un hijo <b>varón</b> es daltónico con probabilidad <b>1/2</b>; un hijo cualquiera, 1/2·1/2 = <b>1/4</b>. Ninguna hija es daltónica.<br>b) X<sup>D</sup>X<sup>d</sup> × X<sup>d</sup>Y: las hijas reciben X<sup>d</sup> del padre y de la madre con probabilidad 1/2 → X<sup>d</sup>X<sup>d</sup> con probabilidad <b>1/2</b>.<br>c) I<sup>A</sup>i × I<sup>B</sup>i → 1/4 I<sup>A</sup>I<sup>B</sup> (AB), 1/4 I<sup>A</sup>i (A), 1/4 I<sup>B</sup>i (B), 1/4 ii (O). Cada hijo es O con probabilidad 1/4; dos hijos: (1/4)² = <b>1/16</b>.<br>d) Los alelos I<sup>A</sup> e I<sup>B</sup> son <b>codominantes</b>: ambos se expresan a la vez, y el individuo tiene los antígenos A y B en sus eritrocitos. El alelo i es recesivo." +
            CR + "a) 0,3 por los genotipos y fenotipos, 0,15 por cada probabilidad; b) 0,2 por el cruce y 0,2 por el resultado; c) 0,3 por los fenotipos y 0,3 por la probabilidad; d) 0,3 por codominancia y 0,1 por los antígenos." },
        { titulo: "Pregunta 5A · Ingeniería genética y mutaciones", puntos: 2,
          enunciado: E5A + "Se dispone de la hebra de ADN 5′-ATGGAATTCCGTAGGCTAGAATTCTTAGC-3′. La enzima de restricción EcoRI reconoce la secuencia GAATTC y corta entre la G y la A (G↓AATTC).<br>a) ¿Cuántos sitios de corte hay y qué tamaños tienen los fragmentos de esta hebra? (0,6)<br>b) Se parte de 100 moléculas de molde y se hacen 25 ciclos de PCR. Calcula cuántas moléculas habrá si cada ciclo duplica el número. (0,5)<br>c) ¿Por qué se utiliza una ADN polimerasa termoestable como la Taq? (0,4)<br>d) La tasa de mutación es de 1·10⁻⁹ por par de bases y replicación. Calcula las mutaciones nuevas por replicación de un genoma diploide humano de 6,4·10⁹ pb y define mutación. (0,5)",
          solucion: "a) Hay <b>2 sitios</b> GAATTC (posiciones 4–9 y 19–24). Se corta tras la G de cada uno, así que se obtienen <b>3 fragmentos</b> de <b>4, 15 y 10 nucleótidos</b> (4 + 15 + 10 = 29). Los extremos generados son cohesivos (AATT).<br>b) N = 100·2²⁵ = 100·33 554 432 ≈ <b>3,36·10⁹ moléculas</b>.<br>c) La PCR alterna ciclos de calentamiento a ~95 °C (desnaturalizar el ADN), ~55 °C (unión de cebadores) y ~72 °C (extensión). Una polimerasa normal se desnaturalizaría en cada ciclo; la <b>Taq</b> (de la bacteria termófila <i>Thermus aquaticus</i>) soporta las altas temperaturas y no hay que añadirla de nuevo.<br>d) Mutaciones por replicación = 1·10⁻⁹ · 6,4·10⁹ = <b>6,4</b> (unas 6 mutaciones nuevas por célula y replicación). <b>Mutación</b>: cambio al azar en la secuencia o estructura del material genético, que puede ser neutro, perjudicial o beneficioso, y es la fuente de nuevos alelos." +
            CR + "a) 0,2 por los sitios, 0,3 por los fragmentos y 0,1 por los extremos cohesivos; b) 0,3 por el planteamiento y 0,2 por el valor; c) 0,2 por los ciclos de temperatura y 0,2 por la termoestabilidad; d) 0,3 por el cálculo y 0,2 por la definición." },
        { titulo: "Pregunta 5B · Inmunología: respuesta primaria y secundaria", puntos: 2,
          enunciado: E5B + "A un voluntario se le administra una vacuna el día 0 y una dosis de refuerzo el día 28. Se mide el título de anticuerpos (inverso de la mayor dilución del suero que da reacción positiva):<br>" +
            tabla(["Día", "0", "7", "14", "28 (refuerzo)", "35", "42", "56"], [["Título", "1", "2", "8", "4", "256", "512", "256"]]) +
            "a) Calcula cuántas veces mayor es el pico de la respuesta secundaria que el de la primaria y compara la rapidez de ambas. (0,5)<br>b) Explica a qué se debe la diferencia. (0,5)<br>c) Diferencia una vacuna de un suero y clasifica cada una según el tipo de inmunidad. (0,5)<br>d) Indica el papel de los linfocitos B, los linfocitos T colaboradores y las células plasmáticas. (0,5)",
          solucion: "a) Pico primario = 8 (día 14); pico secundario = 512 (día 42): 512/8 = <b>64 veces mayor</b> (2⁶). Además la secundaria es más rápida: a los 7 días del refuerzo el título ya es 256, mientras que 7 días después de la primera dosis era solo 2.<br>b) En la primera exposición, el antígeno activa linfocitos B vírgenes, que proliferan y se diferencian en <b>células plasmáticas</b> (secretan anticuerpos) y en <b>células de memoria</b>. En el refuerzo, las <b>células de memoria</b> reconocen el antígeno de forma inmediata y generan en pocos días muchas más células plasmáticas.<br>c) La <b>vacuna</b> contiene antígenos (atenuados, inactivados o fragmentos) que hacen que el organismo fabrique sus anticuerpos y memoria: inmunidad <b>activa artificial</b>, duradera y que tarda en aparecer. El <b>suero</b> contiene anticuerpos ya fabricados: inmunidad <b>pasiva artificial</b>, inmediata pero temporal y sin memoria.<br>d) Los <b>linfocitos B</b> reconocen el antígeno con su anticuerpo de membrana y, activados, se diferencian; los <b>linfocitos T colaboradores</b> (Th) liberan citocinas que activan a los linfocitos B (y a los T citotóxicos); las <b>células plasmáticas</b> producen y secretan grandes cantidades de anticuerpos específicos." +
            CR + "a) 0,25 por el factor 64 y 0,25 por la rapidez; b) 0,2 por la respuesta primaria y 0,3 por las células de memoria; c) 0,25 por cada una con su tipo de inmunidad; d) 0,15 + 0,2 + 0,15." }
      ] },

    // ------------------------------------------------------------------ sim8
    { id: "sim8", titulo: "Simulacro 8 · Biología II (formato PAU Madrid 2026)", tipo: "ciencias",
      bloques: [
        { titulo: "Pregunta 1 (obligatoria) · Evolución y genética de poblaciones", puntos: 2,
          enunciado: INSTR + "El alelo S de la β-globina causa anemia falciforme en homocigosis (SS), pero los heterocigotos (AS) son más resistentes a la malaria. Se han genotipado 1000 personas en dos zonas:<br>" +
            tabla(["Zona", "AA", "AS", "SS"], [["A (con malaria)", "515", "410", "75"], ["B (sin malaria)", "900", "98", "2"]]) +
            "a) Calcula la frecuencia del alelo S en cada zona. (0,6)<br>b) ¿Está la zona A en equilibrio de Hardy-Weinberg? Compara los números esperados con los observados. (0,5)<br>c) Explica por qué la frecuencia de S es mayor en la zona A. (0,5)<br>d) Indica qué cambio molecular origina el alelo S y de qué tipo de mutación se trata. (0,4)",
          solucion: "a) Cada persona tiene 2 alelos (2000 en total). Zona A: q = (410 + 2·75)/2000 = 560/2000 = <b>0,28</b>. Zona B: q = (98 + 2·2)/2000 = 102/2000 = <b>0,051</b>.<br>b) En A, p = 0,72 y q = 0,28. Esperados: AA = p²·1000 = 518,4; AS = 2pq·1000 = 403,2; SS = q²·1000 = 78,4. Observados: 515, 410 y 75. Las diferencias son pequeñas (menos de 8 individuos), así que <b>es compatible con el equilibrio de Hardy-Weinberg</b>.<br>c) Es un caso de <b>selección natural con ventaja del heterocigoto</b> (selección equilibradora): en la zona con malaria los AS sobreviven y se reproducen más que los AA (más sensibles a la malaria) y que los SS (anemia grave), y el alelo S se mantiene en frecuencia elevada. En B no hay esa ventaja y la selección contra SS reduce su frecuencia.<br>d) Es una <b>mutación puntual por sustitución de una base</b> en el gen de la β-globina (GAG → GTG): en la proteína, el ácido glutámico (Glu) se sustituye por valina (Val), lo que hace que la hemoglobina S polimerice en baja concentración de O₂ y deforme los eritrocitos. Es una mutación de cambio de sentido." +
            CR + "a) 0,3 por cada zona; b) 0,3 por los esperados y 0,2 por la conclusión; c) 0,3 por la ventaja del heterocigoto y 0,2 por la comparación entre zonas; d) 0,2 por la sustitución GAG → GTG y 0,2 por Glu → Val y el tipo de mutación." },
        { titulo: "Pregunta 2A · Lípidos y metabolismo energético", puntos: 2,
          enunciado: E2A + "El ácido palmítico (C₁₆H₃₂O₂, M = 256 g/mol) es un ácido graso saturado de 16 carbonos que se degrada en la mitocondria mediante la β-oxidación.<br>a) ¿Cuántas vueltas de β-oxidación se necesitan y cuántas moléculas de acetil-CoA se forman? (0,5)<br>b) Cada vuelta produce 1 FADH₂ y 1 NADH, y cada acetil-CoA rinde 10 ATP en el ciclo de Krebs y la cadena respiratoria (2,5 por NADH, 1,5 por FADH₂). La activación del ácido graso gasta 2 ATP. Calcula el ATP neto. (0,8)<br>c) Compara el ATP por gramo del ácido palmítico con el de la glucosa (M = 180 g/mol; 32 ATP por molécula). (0,4)<br>d) ¿Por qué las grasas son la principal reserva energética a largo plazo? (0,3)",
          solucion: "a) Cada vuelta acorta la cadena en 2 carbonos y libera un acetil-CoA. Con 16 carbonos: <b>7 vueltas</b> y <b>8 acetil-CoA</b> (la última vuelta da 2 acetil-CoA).<br>b) 8 acetil-CoA · 10 = 80 ATP; 7 FADH₂ · 1,5 = 10,5 ATP; 7 NADH · 2,5 = 17,5 ATP. Total = 108 ATP; menos 2 de la activación: <b>106 ATP netos</b>.<br>c) Palmítico: 106/256 = <b>0,41 ATP/g</b>. Glucosa: 32/180 = <b>0,18 ATP/g</b>. El ácido graso rinde unas <b>2,3 veces más</b> energía por gramo, porque está más reducido (más H por carbono) y se oxida más.<br>d) Los lípidos son <b>muy reducidos</b> (≈ 9 kcal/g frente a ≈ 4 kcal/g) y <b>hidrófobos</b>: se almacenan en los adipocitos sin agua, mientras que el glucógeno retiene mucha agua. Ocupan menos volumen y pesan menos para la misma energía." +
            CR + "a) 0,25 por cada dato; b) 0,3 por el ATP de los acetil-CoA, 0,3 por NADH y FADH₂ y 0,2 por restar la activación; c) 0,3 por los dos cálculos y 0,1 por la comparación; d) 0,15 por cada razón (hasta 0,3)." },
        { titulo: "Pregunta 2B · Glúcidos", puntos: 2,
          enunciado: E2B + "La sacarosa (C₁₂H₂₂O₁₁, M = 342 g/mol) es un disacárido formado por glucosa y fructosa (C₆H₁₂O₆, M = 180 g/mol).<br>a) Escribe la reacción de formación e indica el tipo de enlace y qué carbonos intervienen. (0,5)<br>b) Calcula las masas de glucosa y de fructosa que se obtienen al hidrolizar 171 g de sacarosa. (0,6)<br>c) Explica por qué la sacarosa no da positivo con el reactivo de Benedict y la maltosa sí. (0,5)<br>d) Compara el almidón y la celulosa: monómero, enlace y función. (0,4)",
          solucion: "a) <b>Glucosa + fructosa → sacarosa + H₂O</b>. Es un enlace <b>O-glucosídico α(1→2)</b> (α en la glucosa, carbono 1; carbono 2 de la fructosa), que une los dos carbonos anoméricos; se libera una molécula de agua.<br>b) Hidrólisis: sacarosa + H₂O → glucosa + fructosa. n(sacarosa) = 171/342 = 0,50 mol → 0,50 mol de glucosa y 0,50 mol de fructosa: 0,50·180 = <b>90 g de glucosa y 90 g de fructosa</b> (comprobación: 171 + 9 g de agua = 180 g).<br>c) El reactivo de Benedict detecta azúcares <b>reductores</b>, que tienen un carbono anomérico libre (grupo carbonilo libre). En la sacarosa los dos carbonos anoméricos forman el enlace, así que <b>no es reductora</b>; en la maltosa (α(1→4)) queda libre el carbono anomérico de una glucosa, por lo que <b>sí reduce</b> el Cu²⁺ y da precipitado rojo.<br>d) Ambos son polímeros de <b>glucosa</b>. <b>Almidón</b>: enlaces <b>α(1→4)</b> (con ramificaciones α(1→6) en la amilopectina), helicoidal; es la reserva energética de las plantas. <b>Celulosa</b>: enlaces <b>β(1→4)</b>, cadenas rectas unidas por puentes de hidrógeno en microfibrillas; función estructural (pared celular vegetal), indigerible para los humanos." +
            CR + "a) 0,2 por la reacción, 0,2 por el enlace y 0,1 por los carbonos; b) 0,3 por los moles y 0,3 por las masas; c) 0,3 por el carbono anomérico y 0,2 por aplicarlo a ambos azúcares; d) 0,2 por el tipo de enlace y 0,2 por las funciones." },
        { titulo: "Pregunta 3A · Meiosis y variabilidad", puntos: 2,
          enunciado: E3A + "Una especie tiene 2n = 6 cromosomas.<br>a) ¿Cuántos cromosomas tiene un gameto? Sin entrecruzamiento, ¿cuántos gametos distintos puede formar un individuo y qué probabilidad hay de que uno contenga los tres cromosomas de origen materno? (0,5)<br>b) ¿Cuántos cigotos genéticamente distintos pueden resultar de la fecundación entre dos individuos de esta especie, sin entrecruzamiento? (0,5)<br>c) ¿Cuántos espermatozoides y cuántos óvulos (y corpúsculos polares) se obtienen de 10 espermatocitos primarios y de 10 ovocitos primarios? (0,6)<br>d) Una célula 2n se divide por mitosis 5 veces seguidas: ¿cuántas células hay y cuántos cromosomas tiene cada una? (0,4)",
          solucion: "a) El gameto es haploide: <b>n = 3 cromosomas</b>. Cada par de homólogos se reparte al azar: 2³ = <b>8 gametos distintos</b>. La probabilidad de que un gameto reciba los tres cromosomas maternos es (1/2)³ = <b>1/8</b>.<br>b) 8 tipos de gametos de un individuo × 8 del otro = <b>64 cigotos</b> distintos.<br>c) Cada espermatocito primario da 4 espermatozoides: 10·4 = <b>40 espermatozoides</b>. Cada ovocito primario da 1 óvulo y 3 corpúsculos polares: <b>10 óvulos y 30 corpúsculos polares</b>.<br>d) La mitosis duplica el número de células en cada ciclo: 2⁵ = <b>32 células</b>, todas con <b>6 cromosomas</b> (2n) e idéntico material genético." +
            CR + "a) 0,15 por n, 0,2 por los 8 gametos y 0,15 por la probabilidad; b) 0,3 por el planteamiento y 0,2 por el resultado; c) 0,2 por los espermatozoides y 0,4 por los óvulos y corpúsculos polares; d) 0,2 por 32 células y 0,2 por los cromosomas." },
        { titulo: "Pregunta 3B · Fotosíntesis: origen del oxígeno y balance", puntos: 2,
          enunciado: E3B + "Se cultivan algas con agua marcada con ¹⁸O (H₂¹⁸O) y CO₂ normal; en otro cultivo, con agua normal y CO₂ marcado (C¹⁸O₂). Solo en el primero el O₂ desprendido es ¹⁸O₂.<br>a) ¿Qué conclusión se extrae sobre el origen del O₂ de la fotosíntesis? (0,5)<br>b) Escribe la ecuación global y calcula el CO₂ consumido y el O₂ liberado (en moles y en gramos) cuando se forman 90 g de glucosa (M = 180 g/mol; C = 12, O = 16). (0,6)<br>c) ¿Dónde ocurre la fase luminosa y qué productos genera? (0,5)<br>d) ¿Qué hace la enzima rubisco en el ciclo de Calvin? (0,4)",
          solucion: "a) El oxígeno marcado procede del agua: el <b>O₂ se origina en la fotólisis del agua</b> (H₂O → ½ O₂ + 2 H⁺ + 2 e⁻) y no del CO₂, cuyo oxígeno acaba en la glucosa y el agua.<br>b) <b>6 CO₂ + 6 H₂O → C₆H₁₂O₆ + 6 O₂</b> (con luz). n(glucosa) = 90/180 = 0,50 mol → n(CO₂) = 6·0,50 = <b>3,0 mol</b> = 3,0·44 = <b>132 g</b>; n(O₂) = <b>3,0 mol</b> = 3,0·32 = <b>96 g</b>. (Comprobación: 132 + 54 g de agua = 90 + 96 g.)<br>c) En las <b>membranas de los tilacoides</b> de los cloroplastos (los fotosistemas, la cadena de electrones y la ATP sintasa). Genera <b>ATP y NADPH</b> (que se usarán en el ciclo de Calvin) y <b>O₂</b> como subproducto.<br>d) La <b>rubisco</b> cataliza la <b>fijación del CO₂</b>: une el CO₂ a la ribulosa-1,5-bisfosfato (RuBP) y forma dos moléculas de 3-fosfoglicerato, primer paso del ciclo de Calvin en el estroma." +
            CR + "a) 0,3 por la conclusión y 0,2 por la fotólisis del agua; b) 0,2 por la ecuación, 0,2 por el CO₂ y 0,2 por el O₂; c) 0,2 por el lugar y 0,3 por los productos; d) 0,2 por la fijación del CO₂ y 0,2 por la RuBP y el 3-fosfoglicerato." },
        { titulo: "Pregunta 4A · Expresión génica: maduración del ARNm", puntos: 2,
          enunciado: E4A + "Un gen eucariota de 3600 pb contiene 5 exones de 180, 210, 240, 300 y 270 pb. Los exones forman íntegramente la región codificante, incluido el codón de parada.<br>a) Calcula la longitud total de los intrones y el tamaño del ARNm maduro codificante. (0,5)<br>b) Calcula el número de aminoácidos de la proteína y su masa aproximada (110 Da por aminoácido). (0,6)<br>c) Por empalme alternativo se omite el exón de 240 pb: ¿cuántos aminoácidos tiene la nueva proteína? ¿Se mantiene el marco de lectura? (0,5)<br>d) Cita tres modificaciones que sufre el ARN en el núcleo antes de salir al citoplasma. (0,4)",
          solucion: "a) Exones: 180 + 210 + 240 + 300 + 270 = <b>1200 nt</b> (ARNm codificante). Intrones: 3600 − 1200 = <b>2400 pb</b> (el 67 % del gen).<br>b) 1200/3 = 400 codones, uno de ellos de parada: <b>399 aminoácidos</b>. Masa ≈ 399·110 = 43 890 Da ≈ <b>43,9 kDa</b>.<br>c) Sin el exón de 240 nt quedan 960 nt = 320 codones, con el de parada: <b>319 aminoácidos</b>. 240 es múltiplo de 3 (80 codones), así que <b>se mantiene el marco de lectura</b>: la proteína es más corta pero no cambia la secuencia del resto.<br>d) <b>Splicing</b> (eliminación de los intrones y unión de los exones), adición de la <b>caperuza</b> de 7-metilguanosina en el extremo 5′ y adición de la <b>cola de poli-A</b> en el extremo 3′." +
            CR + "a) 0,3 por los intrones y 0,2 por el ARNm; b) 0,3 por 399 y 0,3 por la masa; c) 0,3 por 319 y 0,2 por el marco de lectura; d) 0,15 por cada modificación (hasta 0,4)." },
        { titulo: "Pregunta 4B · Genética mendeliana: dihibridismo", puntos: 2,
          enunciado: E4B + "En el guisante, la semilla amarilla (A) domina sobre la verde (a) y la lisa (B) sobre la rugosa (b); los genes están en cromosomas distintos. Se cruza AaBb × AaBb.<br>a) Escribe los gametos y la proporción fenotípica esperada. (0,6)<br>b) Calcula la probabilidad de una semilla amarilla y rugosa y la de una verde y rugosa. (0,4)<br>c) Se obtienen 640 semillas: 340 amarillas lisas, 130 amarillas rugosas, 125 verdes lisas y 45 verdes rugosas. Calcula el valor de χ² = Σ(O − E)²/E y decide si es compatible con la proporción esperada (valor crítico 7,81 para 3 grados de libertad y p = 0,05). (0,6)<br>d) ¿Qué ley de Mendel se cumple? (0,4)",
          solucion: "a) Gametos de cada progenitor: <b>AB, Ab, aB, ab</b> (1/4 cada uno). Fenotipos de la descendencia: 9 amarillas lisas : 3 amarillas rugosas : 3 verdes lisas : 1 verde rugosa → <b>9 : 3 : 3 : 1</b> (16 combinaciones).<br>b) Amarilla y rugosa (A_bb): <b>3/16</b>. Verde y rugosa (aabb): <b>1/16</b>.<br>c) Esperados con 640 semillas: 9/16·640 = 360; 3/16·640 = 120; 3/16·640 = 120; 1/16·640 = 40. χ² = (340 − 360)²/360 + (130 − 120)²/120 + (125 − 120)²/120 + (45 − 40)²/40 = 1,11 + 0,83 + 0,21 + 0,63 = <b>2,78</b>. Como 2,78 &lt; 7,81, <b>no se rechaza</b> la hipótesis: los resultados son compatibles con 9 : 3 : 3 : 1 (las diferencias se explican por el azar).<br>d) La <b>tercera ley de Mendel</b> (de la independencia o segregación independiente de caracteres): los alelos de genes situados en cromosomas distintos se transmiten de forma independiente." +
            CR + "a) 0,3 por los gametos y 0,3 por la proporción; b) 0,2 por cada probabilidad; c) 0,2 por los esperados, 0,2 por χ² y 0,2 por la conclusión; d) 0,3 por la ley y 0,1 por el enunciado." },
        { titulo: "Pregunta 5A · Virus y bacteriófagos", puntos: 2,
          enunciado: E5A + "Para titular una suspensión de bacteriófagos, se diluye 10⁶ veces, se siembran 0,1 mL sobre un césped de bacterias y se cuentan 58 calvas (zonas de lisis).<br>a) Calcula las unidades formadoras de placa (UFP) por mL de la suspensión original. (0,6)<br>b) Describe las etapas del ciclo lítico y di en qué se diferencia del ciclo lisogénico. (0,6)<br>c) Cada fago infecta una bacteria y libera 100 fagos nuevos. Si se parte de un fago, ¿cuántos hay tras 3 ciclos líticos? (0,4)<br>d) ¿Qué demostraron Hershey y Chase con fagos marcados con ³²P y ³⁵S? (0,4)",
          solucion: "a) 58 calvas en 0,1 mL → 580 UFP/mL en la dilución 10⁻⁶. Suspensión original: 580·10⁶ = <b>5,8·10⁸ UFP/mL</b>.<br>b) <b>Ciclo lítico</b>: <b>adsorción</b> (unión a receptores), <b>penetración</b> del ácido nucleico, <b>replicación</b> del genoma y síntesis de proteínas con la maquinaria de la bacteria, <b>ensamblaje</b> de nuevos fagos y <b>lisis</b> con liberación. En el ciclo <b>lisogénico</b> el ADN del fago se integra en el cromosoma bacteriano (profago) y se replica con él, sin destruir la bacteria; puede pasar al ciclo lítico más tarde.<br>c) Cada ciclo multiplica por 100: 100³ = <b>10⁶ fagos</b> (1 → 100 → 10 000 → 1 000 000).<br>d) El ³²P marca el ADN y el ³⁵S las proteínas. Tras la infección, el ³²P entraba en la bacteria y el ³⁵S quedaba fuera: el <b>ADN es el material genético</b> que dirige la producción de nuevos fagos." +
            CR + "a) 0,3 por la dilución y el volumen y 0,3 por el resultado; b) 0,4 por las etapas y 0,2 por la diferencia; c) 0,2 por 100³ y 0,2 por el valor; d) 0,2 por la marca de cada molécula y 0,2 por la conclusión." },
        { titulo: "Pregunta 5B · Inmunología: factor Rh y transfusiones", puntos: 2,
          enunciado: E5B + "Una mujer Rh⁻ (dd) y un hombre Rh⁺ heterocigótico (Dd) esperan un hijo.<br>a) ¿Qué probabilidad hay de que un hijo sea Rh⁺? ¿Y de que de dos hijos al menos uno lo sea? (0,5)<br>b) Explica la enfermedad hemolítica del recién nacido y cómo se previene. (0,6)<br>c) ¿Qué hijo Rh⁺ de la pareja puede llevar al embarazo siguiente a una situación de riesgo y por qué? (0,5)<br>d) Una persona del grupo O⁻ necesita sangre. ¿De qué grupos puede recibirla? Razona con los anticuerpos. (0,4)",
          solucion: "a) dd × Dd → 1/2 Dd (Rh⁺) y 1/2 dd (Rh⁻): <b>1/2</b>. Al menos un Rh⁺ de dos hijos = 1 − P(ambos Rh⁻) = 1 − (1/2)² = <b>3/4</b>.<br>b) Si la madre Rh⁻ gesta un hijo Rh⁺, durante el parto pasan eritrocitos fetales a su sangre: su sistema inmune se sensibiliza y fabrica <b>anticuerpos anti-D</b> y células de memoria. En un embarazo posterior con un feto Rh⁺, los anticuerpos IgG atraviesan la placenta y destruyen los eritrocitos del feto (<b>anemia hemolítica</b>). Se previene administrando a la madre, en las primeras 72 h tras el parto, <b>inmunoglobulina anti-D</b> (inmunidad pasiva), que elimina los eritrocitos fetales antes de que la madre se sensibilice.<br>c) El <b>primer hijo Rh⁺</b> (por la sensibilización en su parto) pone en riesgo al <b>siguiente</b> hijo si este también es Rh⁺ (probabilidad 1/2). Si el siguiente fuera Rh⁻ (dd) no habría problema.<br>d) El grupo O⁻ tiene anticuerpos anti-A y anti-B (y puede fabricar anti-D). Solo puede recibir de <b>O⁻</b>, porque los eritrocitos de los grupos A, B o AB tienen antígenos A o B y se aglutinarían, y los Rh⁺ tendrían el antígeno D. (El O⁻ es en cambio donante universal.)" +
            CR + "a) 0,25 por cada probabilidad; b) 0,3 por la sensibilización y los anticuerpos, 0,1 por el paso por la placenta y 0,2 por la prevención; c) 0,3 por identificar al primer hijo Rh⁺ y 0,2 por la probabilidad o la razón; d) 0,2 por el grupo y 0,2 por el razonamiento." }
      ] }
  ]);
})(typeof window !== "undefined" ? window : globalThis);
